// Kiro's balance reflex (GOLEM_REFLEX=kiro). Steps into a push by adding the transient part of the
// pelvis velocity error (body frame) to the operator's command. Slow, steady errors (a payload, a
// slope) are filtered out by a low-pass estimate, so only sudden disturbances trigger a step.
import type { ReflexState } from './reflex.js';

/** Feedback gain on the transient velocity error (ratio). */
const GAIN = 1.0;
/** Transient velocity error below this is ignored, in m/s. */
const DEADBAND = 0.25;
/** Time constant of the steady-error estimate, in s. */
const TAU = 1.0;
/** Control_Step, in s. */
const DT = 0.02;

const dead = (e: number): number => (Math.abs(e) <= DEADBAND ? 0 : e - Math.sign(e) * DEADBAND);

export class KiroReflex {
  private sx = 0;
  private sy = 0;
  private started = false;

  reset(): void { this.sx = 0; this.sy = 0; this.started = false; }

  command(s: ReflexState, base: ArrayLike<number>, out: Float64Array): void {
    const q = s.qpos, w = q[3] as number, x = q[4] as number, y = q[5] as number, z = q[6] as number;
    const vx = s.qvel[0] as number, vy = s.qvel[1] as number;
    const yaw = Math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
    const c = Math.cos(yaw), sn = Math.sin(yaw);
    const ex = c * vx + sn * vy - (base[0] as number);
    const ey = -sn * vx + c * vy - (base[1] as number);
    if (!this.started) { this.sx = ex; this.sy = ey; this.started = true; }
    const a = DT / TAU;
    this.sx += a * (ex - this.sx);
    this.sy += a * (ey - this.sy);
    out[0] = (base[0] as number) + GAIN * dead(ex - this.sx);
    out[1] = (base[1] as number) + GAIN * dead(ey - this.sy);
    out[2] = base[2] as number;
  }
}

