// Kiro's balance reflex (GOLEM_REFLEX=kiro). Steps sideways into a lateral push: the lateral pelvis
// velocity error (body frame, beyond a dead band) is added to the operator's lateral command. The
// forward command and the yaw rate pass through unchanged. Allocates nothing; holds no state.
import type { ReflexState } from './reflex.js';

/** Feedback gain on the lateral velocity error (ratio). */
const GAIN = 1.0;
/** Lateral velocity error below this is ignored, in m/s. */
const DEADBAND = 0.25;

const dead = (e: number): number => (Math.abs(e) <= DEADBAND ? 0 : e - Math.sign(e) * DEADBAND);

export class KiroReflex {
  reset(): void {}

  command(s: ReflexState, base: ArrayLike<number>, out: Float64Array): void {
    const q = s.qpos, w = q[3] as number, x = q[4] as number, y = q[5] as number, z = q[6] as number;
    const yaw = Math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
    // World-frame velocity (m/s) rotated into the heading frame: lateral component.
    const vyBody = -Math.sin(yaw) * (s.qvel[0] as number) + Math.cos(yaw) * (s.qvel[1] as number);
    out[0] = base[0] as number;
    out[1] = (base[1] as number) + GAIN * dead(vyBody - (base[1] as number));
    out[2] = base[2] as number;
  }
}

